/**
 * AMD Javascript module for alumni profile portal page.
 *
 * @module     local_alumni/portal
 * @package    local_alumni
 * @copyright  2026 Digilians
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define('local_alumni/portal', ['jquery', 'core/ajax', 'core/notification', 'core/str'], function($, Ajax, Notification, Str) {

    var Portal = {
        /**
         * Initialize the profile portal logic.
         */
        init: function() {
            var self = this;
            this.userId = parseInt(document.getElementById('alumni-portal-main').getAttribute('data-userid'));
            this.oppOffset = 5; // Starts after first 5 opportunities

            // 1. Track card click → call save_track → update UI badge
            $('.track-select-card').on('click', function() {
                var card = $(this);
                var trackKey = card.data('track');
                self.saveTrack(trackKey, card);
            });

            // 2. KPI tab toggle → show/hide tab content (pure JS, no jQuery show/hide)
            $('.kpi-tab-trigger').on('click', function() {
                var btn = $(this);
                var targetId = btn.data('kpi-target');

                // Toggle buttons
                document.querySelectorAll('.kpi-tab-trigger').forEach(function(trigger) {
                    trigger.classList.remove('active-trigger');
                });
                btn.addClass('active-trigger');

                // Toggle panes
                document.querySelectorAll('.kpi-tab-content-panel').forEach(function(pane) {
                    pane.style.display = 'none';
                    pane.classList.remove('active-panel');
                });
                
                var targetPane = document.getElementById(targetId);
                if (targetPane) {
                    targetPane.style.display = 'block';
                    targetPane.classList.add('active-panel');
                }

                // Update main dashboard metrics with class "alumni-metrics-group-grid"
                var period = targetId.replace('kpi-tab-', '');
                var dataItem = $('.kpi-data-item[data-period="' + period + '"]');
                if (dataItem.length) {
                    var engagement = parseFloat(dataItem.data('engagement'));
                    var projects = parseInt(dataItem.data('projects'));
                    var satisfaction = parseFloat(dataItem.data('satisfaction'));
                    var trainings = parseInt(dataItem.data('trainings'));

                    $('#main-metric-performance').text(satisfaction + '%');
                    $('#main-metric-certificates').text(trainings);
                    $('#main-metric-projects').text(projects);
                    $('#main-metric-engagement').text(engagement + '%');
                }
            });

            // 3. "عرض الكل" opportunities → call get_opportunities with offset → append cards
            $('#btn-load-more-opps').on('click', function() {
                self.loadMoreOpportunities();
            });

            // 4. Notification click → mark as read via AJAX → toggle read style
            $('.notification-panel-item').on('click', function() {
                var item = $(this);
                var notifId = item.data('notifid');
                if (item.hasClass('unread-item')) {
                    self.markNotificationRead(notifId, item);
                }
            });

            // 5. Profile update button → simple form validation → AJAX save
            $('#btn-update-profile-ajax').on('click', function() {
                self.toggleProfileEdit();
            });

            // 6. KPI Edit modal triggers
            $('#btn-edit-kpis-ajax').on('click', function() {
                var activePeriod = $('.kpi-tab-trigger.active-trigger').data('kpi-target').replace('kpi-tab-', '');
                $('#kpi-period-select').val(activePeriod);
                self.loadKpiFields(activePeriod);
                $('#kpi-edit-modal').fadeIn(200);
            });

            $('#kpi-modal-close-btn, #btn-cancel-kpis').on('click', function() {
                $('#kpi-edit-modal').fadeOut(200);
            });

            // Close modal when clicking outside content box
            $(window).on('click', function(e) {
                if ($(e.target).is('#kpi-edit-modal')) {
                    $('#kpi-edit-modal').fadeOut(200);
                }
            });

            $('#kpi-period-select').on('change', function() {
                self.loadKpiFields($(this).val());
            });

            $('#kpi-edit-form').on('submit', function(e) {
                e.preventDefault();
                self.saveKpis();
            });

            // 7. Gig management triggers
            this.sesskey = document.getElementById('alumni-portal-main').getAttribute('data-sesskey');

            $('#btn-add-gig-ajax-trigger').on('click', function() {
                $('#gig-id-input').val('0');
                $('#gig-title-input').val('');
                $('#gig-platform-input').val('');
                $('#gig-budget-input').val('');
                $('#gig-modal-title-text').html('<i class="fa-solid fa-laptop-code" style="color: var(--track-freelance); margin-left: 8px;"></i>إضافة مشروع حر');
                $('#gig-edit-modal').fadeIn(200);
            });

            $('.btn-edit-gig-trigger').on('click', function() {
                var item = $(this).closest('.gig-list-item');
                var gigId = item.data('gigid');
                var title = item.data('title');
                var platform = item.data('platform');
                var budget = item.data('budget');

                $('#gig-id-input').val(gigId);
                $('#gig-title-input').val(title);
                $('#gig-platform-input').val(platform);
                $('#gig-budget-input').val(budget);
                $('#gig-modal-title-text').html('<i class="fa-solid fa-laptop-code" style="color: var(--track-freelance); margin-left: 8px;"></i>تعديل مشروع حر');
                $('#gig-edit-modal').fadeIn(200);
            });

            $('.btn-delete-gig-trigger').on('click', function() {
                var item = $(this).closest('.gig-list-item');
                var gigId = item.data('gigid');
                self.deleteGig(gigId);
            });

            $('#gig-modal-close-btn, #btn-cancel-gig').on('click', function() {
                $('#gig-edit-modal').fadeOut(200);
            });

            // Close gig modal when clicking outside content box
            $(window).on('click', function(e) {
                if ($(e.target).is('#gig-edit-modal')) {
                    $('#gig-edit-modal').fadeOut(200);
                }
            });

            $('#gig-edit-form').on('submit', function(e) {
                e.preventDefault();
                self.saveGig();
            });

            // 8. Opportunity application triggers
            $('#opportunities-vertical-list').on('click', '.btn-apply-opp-trigger', function() {
                var btn = $(this);
                var oppId = btn.data('oppid');
                var title = btn.data('title');

                $('#apply-opp-id').val(oppId);
                $('#apply-modal-title').text('التقدم لفرصة: ' + title);
                $('#apply-notes').val('');
                $('#apply-opportunity-modal').css('display', 'flex');
            });

            $('#btn-close-apply-modal, #btn-cancel-apply').on('click', function() {
                $('#apply-opportunity-modal').css('display', 'none');
            });

            // Close apply modal when clicking outside content box
            $(window).on('click', function(e) {
                if ($(e.target).is('#apply-opportunity-modal')) {
                    $('#apply-opportunity-modal').css('display', 'none');
                }
            });

            $('#apply-opportunity-form').on('submit', function(e) {
                e.preventDefault();
                self.submitApplication();
            });
        },

        /**
         * Save active track via external API.
         */
        saveTrack: function(trackKey, card) {
            var self = this;
            var promises = Ajax.call([{
                methodname: 'local_alumni_save_track',
                args: {
                    userid: this.userId,
                    track: trackKey
                }
            }]);

            promises[0].done(function(response) {
                if (response.success) {
                    // Update header badge and track cards dynamically
                    $('.track-select-card').removeClass(function(index, className) {
                        return (className.match(/(^|\s)active-\S+/g) || []).join(' ');
                    });
                    card.addClass('active-' + trackKey);

                    // Update header badge text dynamically
                    Str.get_string('track_' + trackKey, 'local_alumni').done(function(localizedTrack) {
                        $('#header-track-badge').html('<i class="fa-solid fa-graduation-cap"></i> ' + localizedTrack);
                    });

                    Notification.addNotification({
                        message: response.message,
                        type: 'success'
                    });
                } else {
                    Notification.addNotification({
                        message: response.message,
                        type: 'error'
                    });
                }
            }).fail(Notification.exception);
        },

        /**
         * Load next batch of opportunities using external API.
         */
        loadMoreOpportunities: function() {
            var self = this;
            var promises = Ajax.call([{
                methodname: 'local_alumni_get_opportunities',
                args: {
                    userid: this.userId,
                    limit: 5,
                    offset: this.oppOffset
                }
            }]);

            promises[0].done(function(opportunities) {
                if (opportunities && opportunities.length > 0) {
                    var container = document.getElementById('opportunities-vertical-list');
                    
                    opportunities.forEach(function(opp) {
                        var card = document.createElement('div');
                        card.className = 'alumni-opportunity-card';
                        card.setAttribute('data-id', opp.id);

                        var deadlineHtml = opp.deadline_label ? '<div class="opp-card-deadline"><i class="fa-regular fa-calendar-days"></i> ' + opp.deadline_label + '</div>' : '';
                        var linkHtml = opp.link ? '<a href="' + opp.link + '" target="_blank" class="opp-card-link-btn">الرابط <i class="fa-solid fa-up-right-from-square"></i></a>' : '';

                        card.innerHTML = 
                            '<div class="opp-card-badge-row">' +
                                '<span class="opp-type-badge type-' + opp.type + '">' + opp.type_label + '</span>' +
                                '<span class="opp-provider-label"><i class="fa-solid fa-building"></i> ' + opp.provider + '</span>' +
                            '</div>' +
                            '<h4 class="opp-card-title">' + opp.title + '</h4>' +
                            deadlineHtml +
                            linkHtml;

                        container.appendChild(card);
                    });

                    self.oppOffset += opportunities.length;
                    if (opportunities.length < 5) {
                        $('#btn-load-more-opps').hide();
                    }
                } else {
                    $('#btn-load-more-opps').hide();
                }
            }).fail(Notification.exception);
        },

        /**
         * Mark notification as read via ajax.php.
         */
        markNotificationRead: function(notifId, item) {
            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: {
                    action: 'mark_read',
                    notifid: notifId
                },
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        item.removeClass('unread-item');
                        item.css('border-right-color', '#e2e8f0');
                        item.css('font-weight', 'normal');
                    }
                }
            });
        },

        /**
         * Toggle profile editing fields inline.
         */
        toggleProfileEdit: function() {
            var self = this;
            var btn = $('#btn-update-profile-ajax');
            var metaBadges = $('.portal-header-badges');
            
            // Check if editing mode is active
            if (btn.hasClass('editing-mode-active')) {
                // Save operation
                var govInput = $('#edit-gov-input-val').val().trim();
                var cohortInput = $('#edit-cohort-input-val').val().trim();

                if (govInput === '' || cohortInput === '') {
                    Notification.addNotification({
                        message: 'يجب ملء كافة الحقول / All fields must be filled',
                        type: 'error'
                    });
                    return;
                }

                $.ajax({
                    url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                    type: 'POST',
                    data: {
                        action: 'update_profile',
                        userid: self.userId,
                        governorate: govInput,
                        cohort_name: cohortInput
                    },
                    dataType: 'json',
                    success: function(response) {
                        if (response.success) {
                            Notification.addNotification({
                                message: response.message,
                                type: 'success'
                            });
                            setTimeout(function() {
                                window.location.reload();
                            }, 1000);
                        } else {
                            Notification.addNotification({
                                message: response.message,
                                type: 'error'
                            });
                        }
                    }
                });
            } else {
                // Enter edit mode
                btn.addClass('editing-mode-active').html('<i class="fa-solid fa-floppy-disk"></i> حفظ التغييرات');
                
                var currentGov = $('.portal-header-badges').find('.fa-location-dot').parent().text().trim();
                var currentCohort = $('.portal-header-badges').find('.fa-users').parent().text().trim();

                // Replace badges with text inputs
                metaBadges.html(
                    '<div style="display:flex; gap:10px; align-items:center; flex-wrap:wrap;">' +
                        '<input type="text" id="edit-gov-input-val" class="form-control form-control-sm" style="width:140px; padding:2px 8px;" value="' + currentGov + '" placeholder="المحافظة">' +
                        '<input type="text" id="edit-cohort-input-val" class="form-control form-control-sm" style="width:140px; padding:2px 8px;" value="' + currentCohort + '" placeholder="الدفعة">' +
                    '</div>'
                );
            }
        },

        /**
         * Load KPI inputs from hidden datastore.
         */
        loadKpiFields: function(period) {
            var dataItem = $('.kpi-data-item[data-period="' + period + '"]');
            if (dataItem.length) {
                $('#kpi-engagement-input').val(dataItem.data('engagement'));
                $('#kpi-projects-input').val(dataItem.data('projects'));
                $('#kpi-competitions-input').val(dataItem.data('competitions'));
                $('#kpi-trainings-input').val(dataItem.data('trainings'));
                $('#kpi-satisfaction-input').val(dataItem.data('satisfaction'));
                $('#kpi-partnerships-input').val(dataItem.data('partnerships'));
            }
        },

        /**
         * Save edited KPI metrics.
         */
        saveKpis: function() {
            var self = this;
            var period = $('#kpi-period-select').val();
            var engagement = $('#kpi-engagement-input').val();
            var projects = $('#kpi-projects-input').val();
            var competitions = $('#kpi-competitions-input').val();
            var trainings = $('#kpi-trainings-input').val();
            var satisfaction = $('#kpi-satisfaction-input').val();
            var partnerships = $('#kpi-partnerships-input').val();

            if (engagement === '' || projects === '' || competitions === '' || trainings === '' || satisfaction === '' || partnerships === '') {
                Notification.addNotification({
                    message: 'يجب ملء كافة الحقول / All fields must be filled',
                    type: 'error'
                });
                return;
            }

            var promises = Ajax.call([{
                methodname: 'local_alumni_update_kpi',
                args: {
                    userid: this.userId,
                    period: period,
                    engagement_rate: parseFloat(engagement),
                    projects_count: parseInt(projects),
                    competitions_count: parseInt(competitions),
                    advanced_trainings: parseInt(trainings),
                    satisfaction_score: parseFloat(satisfaction),
                    partnerships_count: parseInt(partnerships)
                }
            }]);

            promises[0].done(function(response) {
                if (response.success) {
                    Notification.addNotification({
                        message: 'تم حفظ مؤشرات الأداء بنجاح / Performance indicators saved successfully!',
                        type: 'success'
                    });
                    setTimeout(function() {
                        window.location.reload();
                    }, 1000);
                } else {
                    Notification.addNotification({
                        message: 'فشل حفظ مؤشرات الأداء / Failed to save performance indicators.',
                        type: 'error'
                    });
                }
            }).fail(Notification.exception);
        },

        /**
         * Save Gig (Add or Edit) via AJAX.
         */
        saveGig: function() {
            var self = this;
            var gigId = $('#gig-id-input').val();
            var title = $('#gig-title-input').val().trim();
            var platform = $('#gig-platform-input').val().trim();
            var budget = $('#gig-budget-input').val().trim();

            if (title === '' || platform === '' || budget === '') {
                Notification.addNotification({
                    message: 'يجب ملء كافة الحقول / All fields must be filled',
                    type: 'error'
                });
                return;
            }

            var action = (gigId === '0') ? 'add_gig' : 'edit_gig';
            var ajaxData = {
                action: action,
                userid: self.userId,
                title: title,
                platform: platform,
                budget: parseFloat(budget),
                sesskey: self.sesskey
            };

            if (action === 'edit_gig') {
                ajaxData.gigid = parseInt(gigId);
            }

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: ajaxData,
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        Notification.addNotification({
                            message: response.message,
                            type: 'success'
                        });
                        setTimeout(function() {
                            window.location.reload();
                        }, 1000);
                    } else {
                        Notification.addNotification({
                            message: response.message,
                            type: 'error'
                        });
                    }
                },
                error: function() {
                    Notification.addNotification({
                        message: 'حدث خطأ في الاتصال بالخادم / Server connection error.',
                        type: 'error'
                    });
                }
            });
        },

        /**
         * Delete Gig via AJAX.
         */
        deleteGig: function(gigId) {
            var self = this;
            var confirmMsg = 'هل أنت متأكد من رغبتك في حذف هذا المشروع نهائياً؟ / Are you sure you want to delete this gig permanently?';
            if (!confirm(confirmMsg)) {
                return;
            }

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: {
                    action: 'delete_gig',
                    gigid: parseInt(gigId),
                    userid: self.userId,
                    sesskey: self.sesskey
                },
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        Notification.addNotification({
                            message: response.message,
                            type: 'success'
                        });
                        setTimeout(function() {
                            window.location.reload();
                        }, 1000);
                    } else {
                        Notification.addNotification({
                            message: response.message,
                            type: 'error'
                        });
                    }
                },
                error: function() {
                    Notification.addNotification({
                        message: 'حدث خطأ في الاتصال بالخادم / Server connection error.',
                        type: 'error'
                    });
                }
            });
        },

        /**
         * Submit opportunity application via AJAX.
         */
        submitApplication: function() {
            var self = this;
            var oppId = $('#apply-opp-id').val();
            var notes = $('#apply-notes').val().trim();

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: {
                    action: 'apply_opportunity',
                    opportunityid: parseInt(oppId),
                    resume_notes: notes,
                    sesskey: self.sesskey
                },
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        Notification.addNotification({
                            message: response.message,
                            type: 'success'
                        });
                        $('#apply-opportunity-modal').css('display', 'none');
                        setTimeout(function() {
                            window.location.reload();
                        }, 1000);
                    } else {
                        Notification.addNotification({
                            message: response.message,
                            type: 'error'
                        });
                    }
                },
                error: function() {
                    Notification.addNotification({
                        message: 'حدث خطأ في الاتصال بالخادم / Server connection error.',
                        type: 'error'
                    });
                }
            });
        }
    };

    return Portal;
});
