/**
 * AMD Javascript module for corporate portal page.
 *
 * @module     local_alumni/corporate
 * @package    local_alumni
 * @copyright  2026 Digilians
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define('local_alumni/corporate', ['jquery', 'core/notification'], function($, Notification) {

    var Corp = {
        /**
         * Initialize corporate logic.
         */
        init: function() {
            var self = this;
            this.userId = parseInt($('#corporate-portal-main').data('userid'));
            this.sesskey = $('#corporate-portal-main').data('sesskey');

            // 1. Company Registration Form Handler
            $('#corp-registration-form').on('submit', function(e) {
                e.preventDefault();
                self.registerCompany();
            });

            // 2. Company Profile Edit Triggers
            $('#btn-edit-corp-profile').on('click', function() {
                $('#corp-profile-modal').css('display', 'flex');
            });

            $('#btn-close-corp-modal, #btn-cancel-corp-edit').on('click', function() {
                $('#corp-profile-modal').css('display', 'none');
            });

            $('#corp-edit-profile-form').on('submit', function(e) {
                e.preventDefault();
                self.updateCompanyProfile();
            });

            // 3. Post/Edit Opportunity Modal Triggers
            $('#btn-post-opp-trigger, #btn-add-opp-top').on('click', function() {
                $('#opp-id-input').val('0');
                $('#opp-title-ar').val('');
                $('#opp-title-en').val('');
                $('#opp-type-select').val('competition');
                $('#opp-deadline-input').val('');
                $('#opp-link-input').val('');
                $('#opp-desc-ar').val('');
                $('#opp-desc-en').val('');
                $('.opp-track-chk').prop('checked', false);
                $('#opp-modal-title').html('<i class="fa-solid fa-briefcase" style="color: var(--primary-indigo); margin-left: 8px;"></i>إضافة فرصة جديدة');
                $('#opp-edit-modal').css('display', 'flex');
            });

            $('#btn-close-opp-modal, #btn-cancel-opp').on('click', function() {
                $('#opp-edit-modal').css('display', 'none');
            });

            $('#opp-edit-form').on('submit', function(e) {
                e.preventDefault();
                self.saveOpportunity();
            });

            // 4. Edit single opportunity trigger
            $('.btn-edit-opp').on('click', function() {
                var card = $(this).closest('.corp-opp-card');
                var oppId = card.data('id');
                var titleAr = card.data('title-ar');
                var titleEn = card.data('title-en');
                var descAr = card.data('desc-ar');
                var descEn = card.data('desc-en');
                var type = card.data('type');
                var deadline = card.data('deadline');
                var link = card.data('link');

                $('#opp-id-input').val(oppId);
                $('#opp-title-ar').val(titleAr);
                $('#opp-title-en').val(titleEn);
                $('#opp-type-select').val(type);
                $('#opp-deadline-input').val(deadline);
                $('#opp-link-input').val(link);
                $('#opp-desc-ar').val(descAr);
                $('#opp-desc-en').val(descEn);

                $('.opp-track-chk').prop('checked', false);
                if (card.data('track-excellence')) $('.opp-track-chk[value="excellence"]').prop('checked', true);
                if (card.data('track-freelance')) $('.opp-track-chk[value="freelance"]').prop('checked', true);
                if (card.data('track-entrepreneur')) $('.opp-track-chk[value="entrepreneurship"]').prop('checked', true);
                if (card.data('track-community')) $('.opp-track-chk[value="community"]').prop('checked', true);
                if (card.data('track-development')) $('.opp-track-chk[value="development"]').prop('checked', true);

                $('#opp-modal-title').html('<i class="fa-solid fa-briefcase" style="color: var(--primary-indigo); margin-left: 8px;"></i>تعديل الفرصة');
                $('#opp-edit-modal').css('display', 'flex');
            });

            // 5. Delete Opportunity Trigger
            $('.btn-delete-opp').on('click', function() {
                var oppId = $(this).data('id');
                self.deleteOpportunity(oppId);
            });

            // 6. Expand/Collapse applications
            $('.btn-toggle-applications').on('click', function() {
                var oppId = $(this).data('id');
                $('#apps-panel-' + oppId).slideToggle(200);
            });

            // 7. Accept/Reject application action
            $('.btn-app-status-action').on('click', function() {
                var btn = $(this);
                var appId = btn.data('appid');
                var status = btn.data('status');
                self.updateApplicationStatus(appId, status, btn);
            });

            // Close modals on clicking outside content box
            $(window).on('click', function(e) {
                if ($(e.target).is('#opp-edit-modal')) {
                    $('#opp-edit-modal').css('display', 'none');
                }
                if ($(e.target).is('#corp-profile-modal')) {
                    $('#corp-profile-modal').css('display', 'none');
                }
            });
        },

        /**
         * Register corporate profile.
         */
        registerCompany: function() {
            var self = this;
            var name = $('#reg-company-name').val().trim();
            var email = $('#reg-contact-email').val().trim();
            var website = $('#reg-website').val().trim();
            var desc = $('#reg-description').val().trim();

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: {
                    action: 'corporate_register',
                    company_name: name,
                    contact_email: email,
                    website: website,
                    description: desc,
                    sesskey: self.sesskey
                },
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        Notification.addNotification({
                            message: response.message,
                            type: 'success'
                        });
                        setTimeout(function() {
                            window.location.reload();
                        }, 1000);
                    } else {
                        Notification.addNotification({
                            message: response.message,
                            type: 'error'
                        });
                    }
                }
            });
        },

        /**
         * Update company profile details.
         */
        updateCompanyProfile: function() {
            var self = this;
            var name = $('#edit-company-name').val().trim();
            var email = $('#edit-contact-email').val().trim();
            var website = $('#edit-website').val().trim();
            var desc = $('#edit-description').val().trim();

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: {
                    action: 'corporate_register',
                    company_name: name,
                    contact_email: email,
                    website: website,
                    description: desc,
                    sesskey: self.sesskey
                },
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        Notification.addNotification({
                            message: response.message,
                            type: 'success'
                        });
                        $('#corp-profile-modal').css('display', 'none');
                        setTimeout(function() {
                            window.location.reload();
                        }, 1000);
                    } else {
                        Notification.addNotification({
                            message: response.message,
                            type: 'error'
                        });
                    }
                }
            });
        },

        /**
         * Save/Update Opportunity.
         */
        saveOpportunity: function() {
            var self = this;
            var oppId = $('#opp-id-input').val();
            var titleAr = $('#opp-title-ar').val().trim();
            var titleEn = $('#opp-title-en').val().trim();
            var type = $('#opp-type-select').val();
            var deadline = $('#opp-deadline-input').val();
            var link = $('#opp-link-input').val().trim();
            var descAr = $('#opp-desc-ar').val().trim();
            var descEn = $('#opp-desc-en').val().trim();

            var tracks = [];
            $('.opp-track-chk:checked').each(function() {
                tracks.push($(this).val());
            });

            if (tracks.length === 0) {
                Notification.addNotification({
                    message: 'يجب اختيار مسار مستهدف واحد على الأقل / Must select at least one track',
                    type: 'error'
                });
                return;
            }

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: {
                    action: 'corporate_post_opportunity',
                    id: parseInt(oppId),
                    title_ar: titleAr,
                    title_en: titleEn,
                    type: type,
                    deadline: deadline,
                    link: link,
                    description_ar: descAr,
                    description_en: descEn,
                    tracks: JSON.stringify(tracks),
                    sesskey: self.sesskey
                },
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        Notification.addNotification({
                            message: response.message,
                            type: 'success'
                        });
                        $('#opp-edit-modal').css('display', 'none');
                        setTimeout(function() {
                            window.location.reload();
                        }, 1000);
                    } else {
                        Notification.addNotification({
                            message: response.message,
                            type: 'error'
                        });
                    }
                }
            });
        },

        /**
         * Delete opportunity.
         */
        deleteOpportunity: function(oppId) {
            var self = this;
            var confirmMsg = 'هل أنت متأكد من رغبتك في حذف هذه الفرصة نهائياً؟ / Are you sure you want to delete this opportunity permanently?';
            if (!confirm(confirmMsg)) {
                return;
            }

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: {
                    action: 'corporate_delete_opportunity',
                    id: parseInt(oppId),
                    sesskey: self.sesskey
                },
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        Notification.addNotification({
                            message: response.message,
                            type: 'success'
                        });
                        setTimeout(function() {
                            window.location.reload();
                        }, 1000);
                    } else {
                        Notification.addNotification({
                            message: response.message,
                            type: 'error'
                        });
                    }
                }
            });
        },

        /**
         * Accept or Reject Application.
         */
        updateApplicationStatus: function(appId, status, btn) {
            var self = this;
            var confirmMsg = status === 'approved' 
                ? 'هل تريد قبول طلب المتقدم لهذه الفرصة؟ / Accept this applicant?'
                : 'هل تريد رفض طلب المتقدم لهذه الفرصة؟ / Reject this applicant?';

            if (!confirm(confirmMsg)) {
                return;
            }

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: {
                    action: 'update_application_status',
                    id: parseInt(appId),
                    status: status,
                    sesskey: self.sesskey
                },
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        Notification.addNotification({
                            message: response.message,
                            type: 'success'
                        });
                        
                        // Dynamically update UI state
                        var td = btn.closest('td');
                        var badge = btn.closest('tr').find('.badge');
                        
                        badge.removeClass('badge-pending badge-success badge-danger');
                        if (status === 'approved') {
                            badge.addClass('badge-success').text('مقبول / Approved');
                        } else {
                            badge.addClass('badge-danger').text('مرفوض / Rejected');
                        }
                        
                        td.html('<span style="font-size: 11px; color: #94a3b8; font-weight: bold;"><i class="fa-solid fa-lock"></i> تم اتخاذ إجراء</span>');
                    } else {
                        Notification.addNotification({
                            message: response.message,
                            type: 'error'
                        });
                    }
                }
            });
        }
    };

    return Corp;
});
