// FILE: local/alumni/amd/src/dashboard.js
// ============================================================

/**
 * AMD Javascript module for alumni manager dashboard page.
 *
 * @module     local_alumni/dashboard
 * @package    local_alumni
 * @copyright  2026 Digilians
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define('local_alumni/dashboard', ['jquery', 'core/ajax', 'core/notification'], function($, Ajax, Notification) {

    var Dashboard = {
        /**
         * Initialize dashboard controls.
         */
        init: function() {
            var self = this;
            this.chart = null;
            this.sesskey = $('#alumni-dashboard-main').data('sesskey');
            this.selectAllMatchingStudents = false;
            this.totalPromoteStudents = 0;
            this.selectAllMatchingAlumni = false;
            this.totalAlumniCount = 0;

            // Initial fetch of alumni list
            this.fetchAlumniRoster(1);

            // Tab switching handler
            $('.alumni-tabs-nav .tab-nav-btn').on('click', function() {
                var btn = $(this);
                var targetTab = btn.data('target');
                
                $('.alumni-tabs-nav .tab-nav-btn').removeClass('active');
                btn.addClass('active');
                
                $('.dashboard-tab-panel').removeClass('active');
                $('#' + targetTab).addClass('active');

                // Load roster/promotion on tab change if needed
                if (targetTab === 'alumni-roster-tab') {
                    self.fetchAlumniRoster(1);
                } else if (targetTab === 'promote-students-tab') {
                    self.fetchNonAlumniStudents(1);
                }
            });

            // 1. Alumni table search → trigger on button click or Enter keypress
            $('#btn-roster-search-submit').on('click', function() {
                self.fetchAlumniRoster(1);
            });

            $('#roster-search-name').on('keypress', function(e) {
                if (e.which === 13) {
                    e.preventDefault();
                    self.fetchAlumniRoster(1);
                }
            });

            $('#roster-filter-track, #roster-filter-gov, #roster-filter-cohort, #roster-sort-by, #roster-filter-employment').on('change', function() {
                self.fetchAlumniRoster(1);
            });

            // 2. Student promotion table filters & search
            var promoteSearchTimeout = null;
            $('#promote-search-name').on('input', function() {
                clearTimeout(promoteSearchTimeout);
                promoteSearchTimeout = setTimeout(function() {
                    self.fetchNonAlumniStudents(1);
                }, 400);
            });

            $('#promote-filter-course, #promote-filter-cohort').on('change', function() {
                self.fetchNonAlumniStudents(1);
            });

            // Single student promote click handler
            $('#promote-table-rows-container').on('click', '.btn-promote-single', function() {
                var btn = $(this);
                var studentId = btn.data('id');
                self.promoteStudent(studentId, btn);
            });

            // "Select All" checkbox
            $('#select-all-students-chk').on('change', function() {
                var isChecked = $(this).is(':checked');
                $('.promote-student-chk').prop('checked', isChecked);
                self.updateSelectAllBanner();
            });

            // Links for selecting all/none students
            $('#lnk-select-all-students').on('click', function(e) {
                e.preventDefault();
                $('.promote-student-chk').prop('checked', true);
                $('#select-all-students-chk').prop('checked', true);
                self.updateSelectAllBanner();
            });

            // Links for selecting none students
            $('#lnk-select-none-students').on('click', function(e) {
                e.preventDefault();
                $('.promote-student-chk').prop('checked', false);
                $('#select-all-students-chk').prop('checked', false);
                self.selectAllMatchingStudents = false;
                self.updateSelectAllBanner();
            });

            // Click listener for select all matching filters banner
            $(document).on('click', '#btn-select-all-matching-filters', function(e) {
                e.preventDefault();
                self.selectAllMatchingStudents = true;
                self.updateSelectAllBanner();
            });

            // Checkbox change listener to update banner state
            $('#promote-table-rows-container').on('change', '.promote-student-chk', function() {
                self.updateSelectAllBanner();
            });

            // Batch promotion handler
