            });

            $('#opps-manager-table-rows').on('click', '.opp-delete-row-btn', function() {
                var oppId = $(this).data('id');
                if (confirm('هل أنت متأكد من رغبتك في حذف هذه الفرصة نهائياً؟')) {
                    self.deleteOpportunityAjax(oppId);
