            $('#opps-manager-table-rows').on('change', '.opp-toggle-active-chk', function() {
                var chk = $(this);
                self.toggleOpportunityActive(chk.data('id'), chk.is(':checked'));
            });

            // 6. CSV export → window.location to export endpoint
            $('#btn-export-csv-download').on('click', function() {
                var search = $('#roster-search-name').val();
                var track = $('#roster-filter-track').val();
                var gov = $('#roster-filter-gov').val();
                var cohort = $('#roster-filter-cohort').val();
                var sortby = $('#roster-sort-by').val() || 'id_desc';

                var exportUrl = M.cfg.wwwroot + '/local/alumni/ajax.php?action=export_csv' +
                    '&search=' + encodeURIComponent(search) +
                    '&track=' + encodeURIComponent(track) +
                    '&governorate=' + encodeURIComponent(gov) +
                    '&cohort=' + encodeURIComponent(cohort) +
                    '&sortby=' + encodeURIComponent(sortby);

                window.location = exportUrl;
            });

            // Quarterly Report Trigger
            $('#btn-trigger-report').on('click', function() {
