        /**
         * Fetch alumni roster table rows.
         */
        fetchAlumniRoster: function(page) {
            var self = this;
            var search = $('#roster-search-name').val();
            var track = $('#roster-filter-track').val();
            var gov = $('#roster-filter-gov').val();
            var cohort = $('#roster-filter-cohort').val();
            var employment = $('#roster-filter-employment').val();
            var sortby = $('#roster-sort-by').val() || 'id_desc';

            // Reset selection state when filters change or page is loaded
            self.selectAllMatchingAlumni = false;
            $('#alumni-select-all-banner').hide();

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'GET',
                data: {
                    action: 'get_alumni_roster',
                    search: search,
                    track: track,
                    governorate: gov,
                    cohort: cohort,
                    employment: employment,
                    sortby: sortby,
                    page: page
                },
                dataType: 'json',
                success: function(response) {
                    self.totalAlumniCount = response.total || 0;
                    self.renderAlumniRows(response.rows);
                    self.renderPagination(response.total_pages, page);
                    $('#select-all-alumni-chk').prop('checked', false);
                    self.updateAlumniSelectAllBanner();
                }
            });
        },

        /**
         * Render table rows dynamically.
         */
        renderAlumniRows: function(rows) {
            var html = '';
            if (rows && rows.length > 0) {
                rows.forEach(function(row) {
                    html += 
                        '<tr data-id="' + row.id + '" data-userid="' + row.userid + '">' +
                            '<td style="text-align: center;">' +
                                '<input type="checkbox" class="alumni-select-chk" data-userid="' + row.userid + '" title="Select">' +
                            '</td>' +
                            '<td>' + row.fullname + '</td>' +
                            '<td>' + row.governorate + '</td>' +
                            '<td class="editable-cell col-cohort-cell" data-field="cohort_name" data-val="' + row.cohort_name + '">' + row.cohort_name + '</td>' +
                            '<td class="editable-cell col-track-cell" data-field="track" data-val="' + row.track + '">' + row.track_label + '</td>' +
                            '<td>' + row.main_category + '</td>' +
                            '<td>' + row.sub_category + '</td>' +
                            '<td>' + row.course_name + '</td>' +
                            '<td style="text-align: center;"><span class="badge badge-info" style="font-size: 13px; background-color: var(--excellence-bg); color: var(--track-excellence); padding: 4px 8px; border-radius: 4px; font-weight: bold;">' + row.gigs_count + '</span></td>' +
                            '<td>' + row.performance_score + '%</td>' +
                            '<td class="editable-cell col-status-cell" data-field="engagement_status" data-val="' + row.engagement_status + '">' + row.status_label + '</td>' +
                            '<td class="editable-cell col-employment-cell" data-field="employment_status" data-val="' + row.employment_status + '">' + row.employment_status_label + '</td>' +
                            '<td>' + row.graduation_date_label + '</td>' +
                            '<td style="display: flex; gap: 10px; justify-content: flex-end; align-items: center;">' +
                                '<a href="' + M.cfg.wwwroot + '/local/alumni/myprofile.php?userid=' + row.userid + '" class="btn btn-sm btn-link" style="padding:0; font-weight:700; color: var(--track-excellence); text-decoration: none; display: inline-flex; align-items: center; gap: 4px;"><i class="fa-solid fa-eye"></i> عرض</a>' +
                                '<button type="button" class="btn btn-sm btn-link btn-add-gig-modal-trigger" data-userid="' + row.userid + '" data-fullname="' + row.fullname + '" style="padding:0; font-weight:700; color: var(--track-freelance); border: none; background: none; cursor: pointer; display: inline-flex; align-items: center; gap: 4px;"><i class="fa-solid fa-plus-circle"></i> مشروع</button>' +
                                '<button type="button" class="btn btn-sm btn-link btn-delete-alumni" data-userid="' + row.userid + '" style="padding:0; font-weight:700; color: #dc2626; border: none; background: none; cursor: pointer; display: inline-flex; align-items: center; gap: 4px;"><i class="fa-solid fa-trash-can"></i> حذف</button>' +
                            '</td>' +
                        '</tr>';
                });
            } else {
                html = '<tr><td colspan="14" style="text-align: center; padding: 20px;">No alumni records match filters.</td></tr>';
            }
            $('#roster-table-rows-container').html(html);
        },

        /**
         * Render pagination controls.
         */
        renderPagination: function(totalPages, currentPage) {
            var self = this;
            var html = '';
            for (var i = 1; i <= totalPages; i++) {
                var activeClass = i === currentPage ? 'active-page' : '';
                html += '<button type="button" class="pagination-btn ' + activeClass + '" data-page="' + i + '">' + i + '</button>';
            }
            $('#roster-pagination-holder').html(html);

            $('#roster-pagination-holder .pagination-btn').on('click', function() {
                var page = $(this).data('page');
                self.fetchAlumniRoster(page);
            });
        },

        /**
         * Render select inputs for inline editable cells.
         */
        makeCellEditable: function(cell) {
            var self = this;
            var field = cell.data('field');
            var val = cell.data('val');

            if (field === 'cohort_name') {
                var inputHtml = '<input type="text" class="form-control form-control-sm" style="width: 100%;" value="' + val + '">';
                cell.html(inputHtml);
                var input = cell.find('input');
                input.focus();

                var hasSaved = false;
                var saveAction = function() {
                    if (hasSaved) return;
                    hasSaved = true;
                    var newVal = input.val().trim();
                    if (newVal !== '' && newVal !== val) {
                        self.saveInlineEditAjax(cell, field, newVal);
                    } else {
                        cell.html(val);
                    }
                };

                input.on('blur', function() {
                    saveAction();
                });

                input.on('keyup', function(e) {
                    if (e.which === 13) { // Enter key
                        saveAction();
                    } else if (e.which === 27) { // ESC key
                        hasSaved = true;
                        cell.html(val);
                    }
                });
                return;
            }

            var selectHtml = '<select class="form-control form-control-sm" style="width: 100%;">';

            if (field === 'track') {
                var tracks = [
                    {key: 'excellence', label: 'التيمز / Excellence'},
                    {key: 'freelance', label: 'العمل الحر / Freelance'},
                    {key: 'entrepreneurship', label: 'ريادة الأعمال / Entrepreneurship'},
                    {key: 'community', label: 'الخدمة المجتمعية / Community'},
                    {key: 'development', label: 'التطوير الرقمي / Development'}
                ];
                tracks.forEach(function(t) {
                    var selected = t.key === val ? 'selected' : '';
                    selectHtml += '<option value="' + t.key + '" ' + selected + '>' + t.label + '</option>';
                });
            } else if (field === 'engagement_status') {
                var statuses = [
                    {key: 'active', label: 'نشط / Active'},
                    {key: 'inactive', label: 'غير نشط / Inactive'},
                    {key: 'ambassador', label: 'سفير / Ambassador'}
                ];
                statuses.forEach(function(s) {
                    var selected = s.key === val ? 'selected' : '';
                    selectHtml += '<option value="' + s.key + '" ' + selected + '>' + s.label + '</option>';
                });
            } else if (field === 'employment_status') {
                var empStatuses = [
                    {key: 'employed', label: 'موظف / Employed'},
                    {key: 'nonemployed', label: 'غير موظف / Non-Employed'}
                ];
                empStatuses.forEach(function(e) {
                    var selected = e.key === val ? 'selected' : '';
                    selectHtml += '<option value="' + e.key + '" ' + selected + '>' + e.label + '</option>';
                });
            }
            selectHtml += '</select>';

            cell.html(selectHtml);
            var select = cell.find('select');
            select.focus();

            select.on('blur change', function() {
                var newVal = select.val();
                self.saveInlineEditAjax(cell, field, newVal);
            });
        },

        /**
         * Save inline edits to DB.
         */
        saveInlineEditAjax: function(cell, field, newVal) {
            var self = this;
            var row = cell.closest('tr');
            var recordId = row.data('id');

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: {
                    action: 'inline_edit',
                    id: recordId,
                    field: field,
                    value: newVal
                },
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        cell.data('val', newVal);
                        cell.html(response.label);
                    } else {
                        Notification.addNotification({
                            message: 'فشل الحفظ / Save failed',
                            type: 'error'
                        });
                        window.location.reload();
                    }
                }
            });
        },

        /**
         * Initialize Chart.js Trend lines.
         */
        initKpiChart: function() {
            var canvas = document.getElementById('kpiDashboardTrendChart');
            if (!canvas) return;

            var ctx = canvas.getContext('2d');
            this.chart = new Chart(ctx, {
                type: 'line',
                data: {
                    labels: ['البداية / Start', '٣ أشهر / 3Mo', '٦ أشهر / 6Mo', '١٢ شهراً / 12Mo'],
                    datasets: [{
                        label: 'معدل التفاعل / Engagement Rate',
                        data: [0, 0, 0, 0],
                        borderColor: '#534AB7',
                        tension: 0.3,
                        fill: false
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            min: 0,
                            max: 100
                        }
                    }
                }
            });

            this.reloadChartData();
        },

        /**
         * Fetch KPI chart trends via AJAX on filter change.
         */
        reloadChartData: function() {
            var self = this;
            if (!this.chart) return;

            var track = $('#chart-filter-track').val();
            var period = $('#chart-filter-period').val();

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'GET',
                data: {
                    action: 'get_chart_data',
                    track: track,
                    period: period
                },
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        self.chart.data.datasets[0].data = response.data;
                        self.chart.update();
                    }
                }
            });
        },

        /**
         * Add/Edit Opportunity.
         */
        saveOpportunityAjax: function() {
            var self = this;
            var oppId = $('#opp-input-id').val();
            var titleAr = $('#opp-input-title-ar').val();
            var titleEn = $('#opp-input-title-en').val();
            var provider = $('#opp-input-provider').val();
            var type = $('#opp-input-type').val();
            var tracks = $('#opp-input-tracks').val(); // JSON array
            var deadline = $('#opp-input-deadline').val();
            var link = $('#opp-input-link').val();
            var descAr = $('#opp-input-desc-ar').val();
            var descEn = $('#opp-input-desc-en').val();

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: {
                    action: 'save_opportunity',
                    id: oppId,
                    title_ar: titleAr,
                    title_en: titleEn,
                    provider: provider,
                    type: type,
                    tracks: JSON.stringify(tracks),
                    deadline: deadline,
                    link: link,
                    desc_ar: descAr,
                    desc_en: descEn,
                    sesskey: this.sesskey
                },
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        Notification.addNotification({
                            message: response.message,
                            type: 'success'
                        });
                        setTimeout(function() {
                            window.location.reload();
                        }, 1000);
                    } else {
                        Notification.addNotification({
                            message: response.message,
                            type: 'error'
                        });
                    }
                }
            });
        },

        /**
         * Edit click binds fields.
         */
        editOpportunityRow: function(row) {
            $('#opp-form-panel-div').slideDown();
            $('#opp-panel-form-title').text('تعديل الفرصة / Edit Opportunity');
            
            $('#opp-input-id').val(row.data('id'));
            $('#opp-input-title-ar').val(row.data('title-ar'));
            $('#opp-input-title-en').val(row.data('title-en'));
            $('#opp-input-provider').val(row.data('provider'));
            $('#opp-input-type').val(row.data('type'));
            $('#opp-input-deadline').val(row.data('deadline'));
            $('#opp-input-link').val(row.data('link'));
            $('#opp-input-desc-ar').val(row.data('desc-ar'));
            $('#opp-input-desc-en').val(row.data('desc-en'));

            // Parse track targets
            var trackVal = row.data('tracks');
            var selectedTracks = [];
            try {
                if (typeof trackVal === 'string') {
                    selectedTracks = JSON.parse(trackVal);
                } else {
                    selectedTracks = trackVal;
                }
            } catch (e) {
                selectedTracks = [];
            }
            $('#opp-input-tracks').val(selectedTracks);

            $('html, body').animate({
                scrollTop: $("#opp-form-panel-div").offset().top - 80
            }, 400);
        },

        /**
         * Delete opportunity using AJAX.
         */
        deleteOpportunityAjax: function(oppId) {
            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: {
                    action: 'delete_opportunity',
                    id: oppId,
                    sesskey: this.sesskey
                },
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        Notification.addNotification({
                            message: response.message,
                            type: 'success'
                        });
                        setTimeout(function() {
                            window.location.reload();
                        }, 1000);
                    }
                }
            });
        },

        /**
