        /**
         * Reset form variables.
         */
        resetOppForm: function() {
            $('#opp-panel-form-title').text('إضافة فرصة جديدة / Add New Opportunity');
            $('#opp-input-id').val('');
            $('#opp-input-title-ar').val('');
            $('#opp-input-title-en').val('');
            $('#opp-input-provider').val('');
            $('#opp-input-type').val('competition');
            $('#opp-input-tracks').val([]);
