        /**
         * Fetch non-alumni students roster.
         */
        fetchNonAlumniStudents: function(page) {
            var self = this;
            var search = $('#promote-search-name').val();
            var courseids = $('#promote-filter-course').val() || [];
            var cohortids = $('#promote-filter-cohort').val() || [];

            // Reset selection state when filters change or page is loaded
            self.selectAllMatchingStudents = false;
            $('#promote-select-all-banner').hide();

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'GET',
                data: {
                    action: 'get_non_alumni_students',
                    search: search,
                    courseids: courseids,
                    cohortids: cohortids,
                    page: page
                },
                dataType: 'json',
                success: function(response) {
                    self.totalPromoteStudents = response.total || 0;
                    
                    // Display count in the tab header
                    if (response.total !== undefined) {
                        $('#promote-students-count').text(response.total).show();
                    } else {
                        $('#promote-students-count').hide();
                    }

                    self.renderNonAlumniRows(response.rows);
                    self.renderPromotePagination(response.total_pages, page);
                    $('#select-all-students-chk').prop('checked', false);
                    self.updateSelectAllBanner();
                }
            });
        },

        /**
         * Render non-alumni table rows.
         */
        renderNonAlumniRows: function(rows) {
            var html = '';
            if (rows && rows.length > 0) {
                rows.forEach(function(row) {
                    html += 
                        '<tr>' +
                            '<td style="text-align: center;">' +
                                '<input type="checkbox" class="promote-student-chk" data-id="' + row.id + '" title="Select">' +
                            '</td>' +
                            '<td>' + row.fullname + '</td>' +
                            '<td>' + row.email + '</td>' +
                            '<td>' +
                                '<button type="button" class="btn btn-sm btn-success btn-promote-single" data-id="' + row.id + '" style="background-color: #22c55e; border: none; font-weight: bold; border-radius: 6px; padding: 4px 10px; color: #fff;">' +
                                    '<i class="fa-solid fa-graduation-cap"></i> ترقية / Promote' +
                                '</button>' +
                            '</td>' +
                        '</tr>';
                });
            } else {
                html = '<tr><td colspan="4" style="text-align: center; padding: 20px;">لا يوجد طلاب غير خريجين يطابقون البحث.</td></tr>';
            }
            $('#promote-table-rows-container').html(html);
        },

        /**
         * Render promote pagination controls.
         */
        renderPromotePagination: function(totalPages, currentPage) {
            var self = this;
            var html = '';
            for (var i = 1; i <= totalPages; i++) {
                var activeClass = i === currentPage ? 'active-page' : '';
                html += '<button type="button" class="pagination-btn ' + activeClass + '" data-page="' + i + '">' + i + '</button>';
            }
            $('#promote-pagination-holder').html(html);

            $('#promote-pagination-holder .pagination-btn').on('click', function() {
                var page = $(this).data('page');
                self.fetchNonAlumniStudents(page);
            });
        },

        /**
         * Promote a single student.
         */
        promoteStudent: function(studentId, btn) {
            var self = this;
            btn.prop('disabled', true).html('<i class="fa-solid fa-spinner fa-spin"></i> ...');

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: {
                    action: 'promote_student',
                    student_id: studentId,
                    sesskey: this.sesskey
                },
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        Notification.addNotification({
                            message: 'تم ترقية الطالب بنجاح! / Promoted successfully',
                            type: 'success'
                        });
                        // Reload lists and stats
                        self.fetchNonAlumniStudents(1);
                        self.fetchAlumniRoster(1);
                        self.refreshDashboardStats();
                    } else {
                        Notification.addNotification({
                            message: response.message || 'فشلت عملية الترقية / Promotion failed',
                            type: 'error'
                        });
                        btn.prop('disabled', false).html('<i class="fa-solid fa-graduation-cap"></i> ترقية / Promote');
                    }
                },
                error: function() {
                    Notification.addNotification({
                        message: 'خطأ في خادم النظام / Server error',
                        type: 'error'
                    });
                    btn.prop('disabled', false).html('<i class="fa-solid fa-graduation-cap"></i> ترقية / Promote');
                }
            });
        },

        /**
         * Promote batch of students.
         */
        promoteSelectedStudents: function(selectedIds) {
            var self = this;
            var search = $('#promote-search-name').val();
            var courseids = $('#promote-filter-course').val() || [];
            var cohortids = $('#promote-filter-cohort').val() || [];

            var ajaxData = {
                action: 'batch_promote_students',
                sesskey: self.sesskey
            };

            if (self.selectAllMatchingStudents) {
                ajaxData.all_matching = 1;
                ajaxData.search = search;
                ajaxData.courseids = courseids;
                ajaxData.cohortids = cohortids;
            } else {
                ajaxData.all_matching = 0;
                ajaxData.user_ids = JSON.stringify(selectedIds);
            }

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: ajaxData,
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        Notification.addNotification({
                            message: response.message,
                            type: 'success'
                        });
                        self.selectAllMatchingStudents = false;
                        self.fetchNonAlumniStudents(1);
                        self.fetchAlumniRoster(1);
                        self.refreshDashboardStats();
                    } else {
                        Notification.addNotification({
                            message: response.message,
                            type: 'error'
                        });
                    }
                },
                error: function() {
                    Notification.addNotification({
                        message: 'حدث خطأ أثناء ترقية الطلاب / Error promoting students',
                        type: 'error'
                    });
                }
            });
        },

        /**
         * Update the select all banner state.
         */
        updateSelectAllBanner: function() {
            var totalChecked = $('.promote-student-chk:checked').length;
            var totalOnPage = $('.promote-student-chk').length;
            
            if (totalChecked === totalOnPage && totalOnPage > 0 && this.totalPromoteStudents > totalOnPage) {
                var text = 'تم تحديد جميع الطلاب في هذه الصفحة (العدد: ' + totalOnPage + ').';
                $('#promote-select-all-banner-text').text(text);
                
                $('#btn-select-all-matching-filters')
                    .text('تحديد جميع الـ ' + this.totalPromoteStudents + ' طلاب المطابقين للبحث / Select all ' + this.totalPromoteStudents + ' matching students')
                    .show();
                
                if (this.selectAllMatchingStudents) {
                    $('#promote-select-all-banner-text').text('تم تحديد جميع الـ ' + this.totalPromoteStudents + ' طلاب المطابقين للبحث.');
                    $('#btn-select-all-matching-filters').hide();
                }
                
                $('#promote-select-all-banner').css('display', 'flex');
            } else {
                this.selectAllMatchingStudents = false;
                $('#promote-select-all-banner').hide();
            }
        },

        /**
         * Update the select all matching alumni banner state.
         */
        updateAlumniSelectAllBanner: function() {
            var totalChecked = $('.alumni-select-chk:checked').length;
            var totalOnPage = $('.alumni-select-chk').length;
            
            if (totalChecked === totalOnPage && totalOnPage > 0 && this.totalAlumniCount > totalOnPage) {
                var text = 'تم تحديد جميع الخريجين في هذه الصفحة (العدد: ' + totalOnPage + '). / Selected all alumni on this page (Count: ' + totalOnPage + ').';
                $('#alumni-select-all-banner-text').text(text);
                
                $('#btn-select-all-matching-alumni')
                    .text('تحديد جميع الـ ' + this.totalAlumniCount + ' خريجين المطابقين للبحث / Select all ' + this.totalAlumniCount + ' matching alumni')
                    .show();
                
                if (this.selectAllMatchingAlumni) {
                    $('#alumni-select-all-banner-text').text('تم تحديد جميع الـ ' + this.totalAlumniCount + ' خريجين المطابقين للبحث. / Selected all ' + this.totalAlumniCount + ' matching alumni.');
                    $('#btn-select-all-matching-alumni').hide();
                }
                
                $('#alumni-select-all-banner').css('display', 'flex');
            } else {
                this.selectAllMatchingAlumni = false;
                $('#alumni-select-all-banner').hide();
            }
        },
        /**
         * Change track for a batch of alumni.
         */
        batchChangeAlumniTrack: function(userIds, track) {
            var self = this;
            var search = $('#roster-search-name').val();
            var filter_track = $('#roster-filter-track').val();
            var gov = $('#roster-filter-gov').val();
            var cohort = $('#roster-filter-cohort').val();

            var ajaxData = {
                action: 'batch_change_track',
                sesskey: self.sesskey,
                track: track
            };

            if (self.selectAllMatchingAlumni) {
                ajaxData.all_matching = 1;
                ajaxData.search = search;
                ajaxData.filter_track = filter_track;
                ajaxData.governorate = gov;
                ajaxData.cohort = cohort;
            } else {
                ajaxData.all_matching = 0;
                ajaxData.user_ids = JSON.stringify(userIds);
            }

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: ajaxData,
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        Notification.addNotification({
                            message: response.message || 'تم تغيير مسار الخريجين المحددين بنجاح / Track updated successfully for selected alumni',
                            type: 'success'
                        });
                        self.selectAllMatchingAlumni = false;
                        self.fetchAlumniRoster(1);
                        $('#select-all-alumni-chk').prop('checked', false);
                    } else {
                        Notification.addNotification({
                            message: response.message || 'فشلت عملية التعديل / Track update failed',
                            type: 'error'
                        });
                    }
                },
                error: function() {
                    Notification.addNotification({
                        message: 'خطأ في خادم النظام / Server error',
                        type: 'error'
                    });
                }
            });
        },

