        /**
         * Save Gig via AJAX.
         */
        saveGigAjax: function() {
            var self = this;
            var userid = $('#gig-input-userid').val();
            var title = $('#gig-input-title').val();
            var platform = $('#gig-input-platform').val();
            var budget = $('#gig-input-budget').val();

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: {
                    action: 'add_gig',
                    userid: userid,
                    title: title,
                    platform: platform,
                    budget: budget,
                    sesskey: this.sesskey
                },
                dataType: 'json',
                success: function(response) {
                    if (response.success) {
                        Notification.addNotification({
                            message: response.message,
                            type: 'success'
                        });
                        $('#add-gig-modal-overlay').css('display', 'none');
                        $('#add-gig-ajax-form')[0].reset();
                        
                        // Reload alumni roster and stats
                        self.fetchAlumniRoster(1);
                        self.refreshDashboardStats();
                    } else {
                        Notification.addNotification({
                            message: response.message,
                            type: 'error'
                        });
                    }
                },
                error: function() {
                    Notification.addNotification({
                        message: 'خطأ في خادم النظام / Server error',
                        type: 'error'
                    });
                }
            });
        },

        importAlumniCsv: function() {
            var self = this;
            var form = $('#alumni-csv-import-form')[0];
            var formData = new FormData(form);
            formData.append('action', 'import_alumni_csv');
            formData.append('sesskey', this.sesskey);

            var submitBtn = $('#btn-submit-csv-import');
            submitBtn.prop('disabled', true).html('<i class="fa-solid fa-spinner fa-spin"></i> جاري الرفع...');

            $.ajax({
                url: M.cfg.wwwroot + '/local/alumni/ajax.php',
                type: 'POST',
                data: formData,
                processData: false,
                contentType: false,
                dataType: 'json',
                success: function(response) {
                    submitBtn.prop('disabled', false).html('<i class="fa-solid fa-upload"></i> رفع واستيراد / Upload & Import');
                    if (response.success) {
                        Notification.addNotification({
                            message: response.message,
                            type: 'success'
                        });
                        $('#csv-import-panel-div').slideUp();
                        form.reset();
                        self.fetchAlumniRoster(1);
                        self.refreshDashboardStats();
                    } else {
                        Notification.addNotification({
                            message: response.message,
                            type: 'error'
                        });
                    }
                },
                error: function() {
                    submitBtn.prop('disabled', false).html('<i class="fa-solid fa-upload"></i> رفع واستيراد / Upload & Import');
                    Notification.addNotification({
                        message: 'حدث خطأ أثناء رفع واستيراد الملف / Error uploading CSV',
                        type: 'error'
                    });
                }
            });
        },

        deleteAlumniAjax: function(userid) {
